      SUBROUTINE FIND8CC     LOCATE MISALIGNMENT THAT MIGHT REFER TO UPDATECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM8F.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM31A.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA      INTEGER         II, III, LFM, NELS, NMARKT, NN, NNN      INTEGER         TYPEM, TYPET, TYT, RORC      EXTERNAL        IDATACC------------------------------------------------------------------------CC     MISALIGNMENT SPECIFICATION IMMEDIATELY FOLLOWING SINGLEC     ELEMENTC      NN = NUM      NELS = 0      NUP(1) = 0C   10 II = ISTOR(NN)      TYPET = IDATA(II)      IF (TYPET .EQ. 3 .OR. TYPET .EQ. 4 .OR. TYPET .EQ. 5      1    .OR. TYPET .EQ. 11 .OR. TYPET .EQ. 14 .OR. TYPET .EQ. 18      2    .OR. TYPET .EQ. 19 .OR. TYPET .EQ. 20 .OR. TYPET .EQ. 25      3    .OR. TYPET .EQ. 28 .OR. TYPET .EQ. 29 .OR. TYPET .EQ. 34      4    .OR. TYPET .EQ. 35 .OR. TYPET .EQ. 36) NELS = NELS + 1      IF (TYPET .EQ. 8) THEN        IF (IDATA(II+9) .EQ. 0) THEN          TYT = INT(DATA(II+7))          LFM = TYT/100          RORC = MOD(TYT,10)          IF (LFM .GE. 1 .AND. RORC .EQ. 0) THEN            NUP(1) = NUP(1) + 1            NIM(1,NUP(1)) = NN          ENDIF        ENDIF      ENDIF      IF (NN .LT. NEL .AND. NELS .LE. 1) THEN        NN = NN + 1        GO TO 10      ENDIFCC     MISALIGNMENT SPECIFICATION REFERRING TO MARKERC      NELS = 0      NN = NUM + 1C   20 II = ISTOR(NN)      TYPET = IDATA(II)      NMARKS = IDATA(II+1)      IF (TYPET .EQ. 31) THEN        NNN = NMARKB   25   III = ISTOR(NNN)        TYPEM = IDATA(III)        IF (TYPEM .EQ. 8) THEN          IF (TIE(III+9) .EQ. 101) THEN            NMARKT = IDATA(III+9)            IF (NMARKS .EQ. NMARKT) THEN                    TYT = INT(DATA(III+7))              LFM = TYT/100              RORC = MOD(TYT,10)              IF (LFM .GE. 1 .AND. RORC .EQ. 0) THEN                NUP(1) = NUP(1) + 1                NIM(1,NUP(1)) = NNN              ENDIF            ENDIF          ENDIF        ENDIF        IF (NNN .LT. NEL .AND. NELS .LE. 1     1      .AND. NNN .LE. NMARKE) THEN          NNN = NNN + 1          GO TO 25        ENDIF      ENDIF      IF (NN .LT. NEL .AND. NELS .LE. 1      1    .AND. NN .LE. NMARKE) THEN        IF (TYPET .EQ. 6 .OR. TYPET .EQ. 10      1      .OR. TYPET .EQ. 13 .OR. TYPET .EQ. 31     2      .OR. TYPET .EQ. 33 .OR. TYPET .EQ. 37     3      .OR. TYPET .EQ. 38) THEN          NN = NN + 1          GO TO 20        ENDIF      ENDIF                                         CC     MISALIGNMENT SPECIFICATION REFERRING TO SINGLE ELEMENTC      IF (NMISRB .EQ. 0 .OR. NMISRE .EQ. 0) GO TO 50      NN = NMISRBC   30 II = ISTOR(NN)      TYPET = IDATA(II)      IF (TYPET .EQ. 8) THEN        NMIS = IDATA(II+9)        IF (TIE(II+9) .EQ. 102 .AND. NMIS .NE. 0) THEN          IF (NMIS .EQ. NUM) THEN                  TYT = INT(DATA(II+7))            LFM = TYT/100            RORC = MOD(TYT,10)            IF (LFM .GE. 1 .AND. RORC .EQ. 0) THEN              NUP(1) = NUP(1) + 1              NIM(1,NUP(1)) = NN            ENDIF          ENDIF        ENDIF      ENDIF      IF (NN .LT. NEL .AND. NELS .LE. 1      1    .AND. NN .LE. NMISRE) THEN        NN = NN + 1        GO TO 30      ENDIF                                       C   50 RETURN      END